-- 4. Case Studies
INSERT INTO case_studies (id, title, slug, client_name, category, summary, context, challenge, solution, results, results_list, technologies, architecture, featured, published_date, screenshots, status, seo, created_at, updated_at) VALUES (1, 'Plateforme ESIIKA — Marketplace Congo-Brazzaville', 'esiika', 'Écosystème ESIIKA · Commerce en Afrique centrale', 'Bokengi Digital & IT · E-Commerce & Full-Stack', 'Conception et déploiement d''une marketplace robuste de mode et d''électronique avec paiement Mobile Money, gestion de stock et logistique de livraison à Brazzaville.', '{"root":{"children":[{"type":"text","text":"Le projet ESIIKA répond au besoin croissant de structuration du commerce en ligne en République du Congo. L''architecture initiale reposait sur un frontend monolithique difficile à maintenir et un backend PHP vulnérable aux attaques de force brute, avec un manque critique de fiabilité dans le traitement des commandes."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Il était impératif de concevoir une plateforme fluide et sécurisée, capable d''exécuter des transactions financières sans faille, de résister aux coupures de connexion fréquentes et de gérer simultanément des milliers de références produits avec des variations de stocks dynamiques."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Les équipes Bokengi ont reconstruit l''application autour d''une architecture découplée : un frontend ultra-rapide sous React et TypeScript optimisé pour mobile, adossé à une API REST sécurisée avec rate-limiting, hachage bcrypt, protection CSRF et validation stricte des entrées. L''infrastructure est conteneurisée avec Docker et servie derrière un reverse-proxy Nginx avec certificats SSL automatisés et passerelles Mobile Money (Airtel Money et MTN)."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"La marketplace est opérationnelle en production sur esiika.com. Le parcours client est entièrement digitalisé : catalogue dynamique, panier persistant, paiement Mobile Money sécurisé et console d''administration commerciale complète."}]}}'::jsonb, '["Plateforme déployée et en production active sur esiika.com","Parcours transactionnel complet : authentification, panier, checkout Mobile Money & Visa","Sécurisation éprouvée du backend : protection CSRF, limitation de débit et secrets hors Git","Temps de chargement réduit de plus de 55% par rapport à la version précédente"]'::jsonb, '[{"name":"React"},{"name":"TypeScript"},{"name":"Node.js"},{"name":"PostgreSQL"},{"name":"Docker"},{"name":"Nginx"},{"name":"Airtel Money API"}]'::jsonb, '{"root":{"children":[{"type":"text","text":"Architecture découplée en micro-services conteneurisés sous Docker Compose. Reverse-proxy Nginx gérant le terminaison SSL et la mise en cache statique. Base de données relationnelle PostgreSQL avec indexation optimisée pour la recherche de produits. Passerelle de webhooks sécurisée pour la confirmation des transactions financières."}]}}'::jsonb, true, '2026-06-15', '[]'::jsonb, 'published', '{"title":"Étude de cas ESIIKA · Marketplace Congo-Brazzaville — Bokengi Group","description":"Découvrez comment Bokengi Group a conçu et sécurisé la marketplace ESIIKA avec intégration Mobile Money et infrastructure Docker."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO case_studies (id, title, slug, client_name, category, summary, context, challenge, solution, results, results_list, technologies, architecture, featured, published_date, screenshots, status, seo, created_at, updated_at) VALUES (2, 'Portail Kongama — Système d''Administration & Gestion Opérationnelle', 'portail-kongama', 'Kongama Group · Direction des Opérations', 'Bokengi Digital & Business · Système d''Information & Gestion', 'Digitalisation des flux documentaires administratifs, automatisation des validations et centralisation des opérations internes pour l''écosystème Kongama.', '{"root":{"children":[{"type":"text","text":"Kongama Group gérait auparavant ses approbations budgétaires, ses bordereaux d''expédition et ses archives documentaires via des processus manuels papier et des feuilles de calcul dispersées, entraînant des pertes de temps considérables et des risques d''erreurs d''imputation."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Créer un portail unique, rigoureusement sécurisé avec contrôle d''accès basé sur les rôles (RBAC), permettant à des dizaines d''agents de collaborer sans goulot d''étranglement avec une traçabilité totale des signatures."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Bokengi a modélisé et développé un portail d''administration réactif en TypeScript et Next.js, connecté à un backend d''automatisation Express/Node.js et une base de données PostgreSQL. Un cluster de cache Redis a été déployé pour accélérer le rendu des tableaux de bord volumineux et gérer les sessions concurrentes."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Le portail Kongama a permis de réduire le délai de validation des dossiers opérationnels de plusieurs jours à quelques heures seulement, tout en assurant un journal d''audit infalsifiable."}]}}'::jsonb, '["Réduction mesurée de 65% des délais de traitement des dossiers administratifs","Traçabilité et journalisation intégrale de 100% des actions et approbations","Gestion granulaire des permissions selon les profils (direction, comptabilité, logistique)","Adoption par 100% des collaborateurs dès le premier mois de déploiement"]'::jsonb, '[{"name":"TypeScript"},{"name":"Next.js"},{"name":"Node.js / Express"},{"name":"PostgreSQL"},{"name":"Redis"},{"name":"Tailwind CSS"}]'::jsonb, '{"root":{"children":[{"type":"text","text":"Architecture en couches avec API REST typée de bout en bout en TypeScript. Authentification basée sur des sessions chiffrées en mémoire Redis. Base PostgreSQL normalisée pour garantir l''intégrité référentielle des documents et des approbations."}]}}'::jsonb, true, '2025-11-20', '[]'::jsonb, 'published', '{"title":"Étude de cas Portail Kongama · Digitalisation Opérationnelle — Bokengi Group","description":"Découvrez comment le portail Kongama a dématérialisé les flux documentaires internes avec TypeScript, Redis et PostgreSQL."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO case_studies (id, title, slug, client_name, category, summary, context, challenge, solution, results, results_list, technologies, architecture, featured, published_date, screenshots, status, seo, created_at, updated_at) VALUES (3, 'Kongama Academy — Plateforme d''Éducation & E-Learning', 'kongama-academy', 'Kongama Academy · Éducation numérique', 'Bokengi Digital & IT · EdTech & Formation Continue', 'Écosystème d''apprentissage numérique connectant formateurs et apprenants, conçu avec une architecture mobile-first PWA optimisée pour l''Afrique.', '{"root":{"children":[{"type":"text","text":"Kongama Academy avait pour ambition de proposer des formations d''excellence en ingénierie et technologies numériques à des étudiants souvent confrontés à des connexions mobiles instables et des forfaits data restreints."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Fournir une interface pédagogique immersive et fluide capable de fonctionner de manière transparente en mode déconnecté, sans compromis sur la richesse interactive des cours."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Bokengi a conçu une Progressive Web App (PWA) de pointe sous React et TypeScript (Vite/Next.js), reposant sur les composants accessibles de Tailwind et shadcn/ui. Les contenus textuels et exercices sont mis en cache localement via Service Workers et synchronisés silencieusement lors de la reconnexion."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"La plateforme est en ligne sur kongama.com. Elle offre un confort d''apprentissage inégalé, avec des temps de navigation instantanés et un taux de rétention d''étudiants largement supérieur aux plateformes d''e-learning traditionnelles."}]}}'::jsonb, '["Plateforme éducative en ligne active sur kongama.com","Architecture PWA complète avec installation écran d''accueil et mode hors-ligne","Temps de chargement initial inférieur à 1.2s sur connexion 3G/4G","Suivi automatisé de la progression des apprenants et délivrance d''attestations"]'::jsonb, '[{"name":"React"},{"name":"TypeScript"},{"name":"Tailwind CSS"},{"name":"Vite / Next.js"},{"name":"shadcn/ui"},{"name":"PWA / Service Workers"}]'::jsonb, '{"root":{"children":[{"type":"text","text":"Frontend moderne PWA avec mise en cache granulaire des ressources statiques et dynamiques via Cache API et IndexedDB. Découpage du code (code-splitting) par module d''apprentissage. API découplée garantissant la légèreté des payloads JSON."}]}}'::jsonb, true, '2026-01-10', '[]'::jsonb, 'published', '{"title":"Étude de cas Kongama Academy · E-learning PWA — Bokengi Group","description":"Conception de l''écosystème Kongama Academy : formation numérique mobile-first, PWA déconnectable et expérience fluide."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO case_studies (id, title, slug, client_name, category, summary, context, challenge, solution, results, results_list, technologies, architecture, featured, published_date, screenshots, status, seo, created_at, updated_at) VALUES (4, 'BisoMapTech — Cartographie Tech & Réseau Sécurisé du Congo', 'bisomaptech', 'Initiative Open Source · Communauté Informatique du Congo', 'Bokengi IT & Cybersécurité · SIG & Cryptographie E2E', 'Plateforme interactive open source qui cartographie et connecte les professionnels de l''informatique au Congo avec messagerie chiffrée de bout en bout.', '{"root":{"children":[{"type":"text","text":"L''écosystème technologique congolais souffrait d''un manque de visibilité globale, les développeurs, administrateurs systèmes et spécialistes cybersécurité travaillant en silos sans moyen de communication sécurisé et souverain."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Cartographier avec précision géographique les talents et communautés à l''échelle nationale, tout en fournissant un canal d''échange direct à l''abri de toute interception ou surveillance."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Bokengi a développé une cartographie interactive géolocalisée sous Leaflet avec synchronisation automatique des profils GitHub. Un protocole de messagerie privée chiffrée de bout en bout (E2E) a été implémenté directement dans le navigateur via l''API Web Cryptography (échange de clés asymétriques ECDH P-256 et chiffrement symétrique AES-GCM 256 bits)."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"BisoMapTech référence plusieurs centaines de profils d''ingénieurs à Brazzaville, Pointe-Noire et dans la diaspora, devenant la référence open source de la tech congolaise."}]}}'::jsonb, '["Cartographie interactive SIG avec recherche multi-critères et géolocalisation","Messagerie chiffrée de bout en bout (ECDH P-256 + AES-GCM) à divulgation nulle","Authentification sécurisée, administration de modération et thèmes dark/light","Code source auditable publié sous licence open source pour la communauté"]'::jsonb, '[{"name":"React"},{"name":"TypeScript"},{"name":"Supabase / PostgreSQL"},{"name":"Leaflet GIS"},{"name":"Web Crypto API"},{"name":"Zustand"}]'::jsonb, '{"root":{"children":[{"type":"text","text":"Architecture client-side zero-knowledge : les clés privées ne quittent jamais le navigateur de l''utilisateur. Base de données distribuée Supabase/PostgreSQL avec politiques de sécurité Row-Level Security (RLS). Rendu cartographique vectoriel tuilé optimisé."}]}}'::jsonb, true, '2025-09-05', '[]'::jsonb, 'published', '{"title":"Étude de cas BisoMapTech · Cartographie Tech Congo — Bokengi Group","description":"Découvrez BisoMapTech : cartographie interactive open source et messagerie chiffrée E2E pour les ingénieurs du Congo."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO case_studies (id, title, slug, client_name, category, summary, context, challenge, solution, results, results_list, technologies, architecture, featured, published_date, screenshots, status, seo, created_at, updated_at) VALUES (5, 'FleetGuard — Télémétrie & Supervision des Équipements Maritimes', 'fleetguard', 'Opérateur Maritime & Gestionnaire de Flotte', 'Bokengi IT & Infrastructure · Monitoring IoT & Supervision d''Actifs', 'Système embarqué et cloud de suivi en temps réel de la conformité des équipements de sécurité critiques à bord de navires avec alertes d''expiration proactives.', '{"root":{"children":[{"type":"text","text":"La gestion des équipements de sauvetage et de sécurité maritime (extincteurs, radeaux de survie, balises de détresse EPIRB) était historiquement consignée sur papier, exposant les armateurs à de lourdes sanctions réglementaires en cas de dépassement de validité."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Assurer la traçabilité continue de centaines d''équipements à bord de bâtiments naviguant en haute mer, avec synchronisation périodique vers les équipes techniques à terre dès la reprise de connectivité portuaire ou satellitaire."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"Bokengi a mis en place une architecture de télémétrie IoT combinant des micro-services Python et un broker de messages MQTT sous Linux Server. Un tableau de bord interactif sous Chart.js et Grafana permet aux commandants de bord et aux armateurs de visualiser instantanément l''état du parc par code couleur et de générer des rapports de conformité certifiés."}]}}'::jsonb, '{"root":{"children":[{"type":"text","text":"FleetGuard garantit 100% de conformité aux audits maritimes internationaux, éliminant tout risque d''immobilisation de navire pour cause de matériel expiré."}]}}'::jsonb, '["Dispositif de télémétrie et synchronisation multi-appareils sécurisée","Système d''alertes automatiques prédictives par code couleur (vert, orange, rouge)","Génération instantanée de rapports de conformité réglementaire aux normes maritimes","Résilience totale : fonctionnement autonome en mer et synchronisation automatique à quai"]'::jsonb, '[{"name":"Python"},{"name":"MQTT Broker"},{"name":"Linux Server"},{"name":"Upstash Redis / PostgreSQL"},{"name":"Chart.js"},{"name":"Grafana"}]'::jsonb, '{"root":{"children":[{"type":"text","text":"Architecture IoT résiliente : passerelle locale à bord communiquant via le protocole léger MQTT. Tampon de données local en cas de coupure de liaison satellitaire. Synchronisation idempotente vers la base cloud dès rétablissement du réseau. Visualisation analytique découplée."}]}}'::jsonb, true, '2025-07-30', '[]'::jsonb, 'published', '{"title":"Étude de cas FleetGuard · Télémétrie Maritime & IoT — Bokengi Group","description":"Supervision des équipements de sécurité maritime avec alertes prédictives, télémétrie IoT et conformité réglementaire par Bokengi IT."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;

-- 5. Posts
INSERT INTO posts (id, title, slug, excerpt, content, author_name, reading_time, status, published_at, categories, tags, seo, created_at, updated_at) VALUES (1, 'Les impératifs de la souveraineté numérique et de l''hébergement résilient en Afrique centrale', 'souverainete-numerique-afrique', 'Face aux défis d''interconnexion, de latence et d''exfiltration des flux sensibles, la relocalisation des infrastructures informatiques et l''adoption de clouds souverains constituent désormais la pierre angulaire de l''indépendance économique des entreprises d''Afrique centrale.', '{"root":{"children":[{"type":"text","text":"La transformation numérique du continent africain traverse un point d''inflexion stratégique. Longtemps tributaires de serveurs hébergés en Europe ou en Amérique du Nord, les entreprises et institutions publiques locales découvrent les limites concrètes de cette dépendance : temps de latence réseau dégradés lors de ruptures de câbles sous-marins, contraintes de conformité réglementaire sur la protection des données personnelles, et exposition aux aléas géopolitiques internationaux.\n\n1. Le coût réel de la dépendance aux infrastructures distantes\nChaque paquet IP qui doit traverser les océans pour être traité par un serveur distant avant de revenir sur le terminal d''un collaborateur local représente non seulement un coût financier direct en bande passante internationale, mais aussi une vulnérabilité opérationnelle. Lorsque le câble WACS ou SAT-3 subit des coupures fortuites, ce sont des pans entiers de la productivité bancaire, logistique ou administrative qui se retrouvent paralysés.\n\n2. Les piliers d''un cloud hybride souverain\nChez Bokengi Group, nous préconisons une architecture pragmatique :\n- Des nœuds de calcul locaux à haute disponibilité (Datacenters Tier III situés sur le territoire national).\n- Des passerelles Edge résilientes capables de continuer à fonctionner en mode dégradé hors ligne (Offline-First).\n- Une réplication chiffrée asynchrone vers des datacenters secondaires distribués pour le plan de reprise d''activité (PRA).\n\n3. Vers une autonomie technologique durable\nBâtir une souveraineté numérique ne signifie pas s''isoler des standards mondiaux, mais maîtriser l''ensemble de la chaîne de valeur : du système d''exploitation Linux durci à la gouvernance des clés cryptographiques, jusqu''à la formation des ingénieurs locaux chargés de l''exploitation. C''est l''engagement quotidien que portent nos divisions d''ingénierie."}]}}'::jsonb, 'Kalel Damba', 5, 'published', '2026-03-01T08:00:00.000Z', '["Infrastructure & Cloud","Souveraineté IT"]'::jsonb, '["Datacenter","Souveraineté","Cloud Privé","Résilience"]'::jsonb, '{"title":"Souveraineté Numérique & Hébergement Résilient en Afrique · Bokengi Group","description":"Analyse stratégique sur la souveraineté numérique, les infrastructures locales et la résilience cloud en Afrique centrale."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO posts (id, title, slug, excerpt, content, author_name, reading_time, status, published_at, categories, tags, seo, created_at, updated_at) VALUES (2, 'Security by Design : intégrer la cryptographie et l''audit continu dès la phase de cadrage', 'security-by-design-systemes-critiques', 'Dans les secteurs bancaires, gouvernementaux et logistiques, la sécurité ne peut plus être un filtre tardif. Découverte de nos pratiques d''ingénierie : chiffrement symétrique et asymétrique, contrôle strict des flux et audits continus de code.', '{"root":{"children":[{"type":"text","text":"Historiquement, la cybersécurité intervenait à la fin d''un projet informatique, sous la forme d''un test d''intrusion hâtif réalisé quelques jours avant la mise en production. Ce modèle est aujourd''hui obsolète et dangereux face à la sophistication des attaques actuelles.\n\n1. Le principe du Security by Design\nIntégrer la sécurité dès la phase de design architectural implique de poser trois questions fondamentales avant même d''écrire la première ligne de code :\n- Quelles données sensibles transitent et où résident-elles au repos (Data at Rest) ?\n- Quels sont les périmètres de confiance stricts (Zero Trust Architecture) entre chaque micro-service ?\n- Que se passe-t-il si un composant ou un tiers est compromis ?\n\n2. Chiffrement de bout en bout et divulgence nulle\nSur des projets d''envergure tels que notre plateforme collaborative BisoMapTech, Bokengi met en œuvre le chiffrement de bout en bout directement au niveau du client web via l''API standard Web Cryptography (ECDH P-256 pour l''échange de clés, AES-GCM 256 bits pour les payloads). Les serveurs d''infrastructure ne détiennent jamais la clé de déchiffrement, garantissant une étanchéité absolue même en cas d''intrusion sur la base de données.\n\n3. Automatisation du pipeline DevSecOps\nLa sécurité n''est pas un état figé, c''est un processus continu :\n- Analyse statique de code (SAST) et détection des secrets intégrées dans chaque Pull Request.\n- Scans réguliers de vulnérabilités sur l''ensemble de l''arbre des dépendances directes et transitives.\n- Revues de code par les pairs systématiques avec principe du moindre privilège appliqué à chaque rôle applicatif."}]}}'::jsonb, 'Équipe Cybersécurité Bokengi', 6, 'published', '2026-02-15T09:30:00.000Z', '["Cybersécurité","Ingénierie Logicielle"]'::jsonb, '["Security by Design","Pentest","E2E Encryption","DevSecOps"]'::jsonb, '{"title":"Security by Design & Cryptographie Appliquée · Bokengi Group","description":"Méthodologie pour concevoir des architectures résilientes, sécurisées dès l''origine et auditées en continu."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO posts (id, title, slug, excerpt, content, author_name, reading_time, status, published_at, categories, tags, seo, created_at, updated_at) VALUES (3, 'Modernisation des systèmes d''information : découplage, APIs et performance opérationnelle', 'modernisation-systemes-information-apis', 'Comment migrer un parc applicatif hétérogène vers une architecture modulaire sans rupture d''exploitation. Analyse des gains apportés par le découplage headless, les APIs sécurisées et les déploiements Edge.', '{"root":{"children":[{"type":"text","text":"Beaucoup d''organisations disposent d''un patrimoine logiciel éprouvé mais enfermé dans des architectures monolithiques rigides. L''ajout d''une fonctionnalité métier ou d''un nouveau canal numérique nécessite des semaines de recettage, avec un risque élevé de régression.\n\n1. L''approche Strangler Fig : moderniser sans tout casser\nPlutôt que d''envisager une réécriture totale « big bang » risquée et coûteuse, Bokengi applique le pattern Strangler Fig (étranglement progressif) :\n- Interposition d''une passerelle d''APIs moderne en amont du système hérité (legacy).\n- Réécriture progressive des domaines métiers isolables sous forme de services découplés.\n- Bascule transparente des flux utilisateur sans interruption de service.\n\n2. Les bénéfices de l''architecture Headless et de l''Edge Computing\nEn séparant clairement la logique métier (CMS Headless, base de données distribuée) de la restitution visuelle (Next.js App Router, Cloudflare Workers), les performances de rendu sont multipliées et les coûts d''infrastructure divisés :\n- Temps de chargement inférieurs à 100 millisecondes grâce au routage Edge mondial.\n- Indépendance totale des équipes produit qui peuvent itérer sur l''interface sans toucher au cœur applicatif.\n- Résilience accrue : si un service tiers faiblit, le site et l''expérience utilisateur restent disponibles grâce à la mise en cache et à l''ISR (Incremental Static Regeneration)."}]}}'::jsonb, 'Direction Ingénierie Digitale', 4, 'published', '2026-01-20T10:00:00.000Z', '["Transformation Digitale","Architecture Logicielle"]'::jsonb, '["Micro-services","APIs","Modernisation SI","Cloudflare Workers"]'::jsonb, '{"title":"Modernisation des Systèmes d''Information & Architecture API · Bokengi Group","description":"Stratégies de transition vers des architectures modulaires, performantes et interopérables."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO posts (id, title, slug, excerpt, content, author_name, reading_time, status, published_at, categories, tags, seo, created_at, updated_at) VALUES (4, 'Note de recherche interne sur les réseaux Mesh (Brouillon non publié)', 'brouillon-interne-non-publie', 'Document de cadrage préliminaire réservé aux équipes internes.', '{"root":{"children":[{"type":"text","text":"Contenu en cours de rédaction. Ne doit pas être exposé sur le frontend public."}]}}'::jsonb, 'Laboratoire R&D Bokengi', 3, 'published', '2026-03-05T12:00:00.000Z', '["R&D","Réseaux"]'::jsonb, '["Mesh","IoT"]'::jsonb, '{"title":"Brouillon R&D · Bokengi Group","description":"Document interne non public."}'::jsonb, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;

